import{_ as e,o as s,c as i,a2 as a}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Formatters","description":"Auto-formatting after agent edits — built-in support for prettier, biome, ruff, gofmt, clang-format, and more, with custom formatter commands.","frontmatter":{"title":"Formatters","description":"Auto-formatting after agent edits — built-in support for prettier, biome, ruff, gofmt, clang-format, and more, with custom formatter commands."},"headers":[],"relativePath":"extending/formatters.md","filePath":"extending/formatters.md"}'),n={name:"extending/formatters.md"};function r(o,t,l,d,h,p){return s(),i("div",null,[...t[0]||(t[0]=[a(`<p>Agents write code fast; formatters keep it boring. After every <code>edit</code>/<code>write</code>/<code>apply_patch</code>, PrioriCode runs the formatter that matches the file — the same one your project would use — so agent-written code is indistinguishable at the diff level. That matters: a formatting churn storm in review is a trust leak.</p><h2 id="built-ins" tabindex="-1">Built-ins <a class="header-anchor" href="#built-ins" aria-label="Permalink to &quot;Built-ins&quot;">​</a></h2><p>Each formatter activates on its own detection rule — the general shape is &quot;the tool exists for this project.&quot; (Prettier, for instance, requires a <code>prettier</code> dependency in a <code>package.json</code> between cwd and worktree <em>and</em> a resolvable binary.):</p><table tabindex="0"><thead><tr><th>Formatter</th><th>Extensions</th></tr></thead><tbody><tr><td>prettier</td><td>JS/TS/JSON/CSS/MD/HTML/YAML and friends</td></tr><tr><td>biome</td><td>same JS/TS/web/config spread as prettier</td></tr><tr><td>oxfmt</td><td>JS/TS variants (experimental — enable with <code>PRIORICODE_EXPERIMENTAL_OXFMT</code>)</td></tr><tr><td>gofmt</td><td><code>.go</code></td></tr><tr><td>ruff / uv</td><td><code>.py</code>, <code>.pyi</code></td></tr><tr><td>mix</td><td><code>.ex</code>, <code>.heex</code> + Elixir family</td></tr><tr><td>clang-format</td><td>C/C++ family</td></tr><tr><td>ktlint</td><td><code>.kt</code>, <code>.kts</code></td></tr><tr><td>rubocop / standardrb / htmlbeautifier</td><td>Ruby + ERB family</td></tr><tr><td>zig, dart, ocamlformat, terraform, latexindent, gleam</td><td>their respective languages</td></tr></tbody></table><p>No formatter installed? Nothing happens — the agent writes as the model produced, minus chaos (the prompt nudges correct style anyway). Install what your repo uses and the pipeline closes itself.</p><h2 id="control-it" tabindex="-1">Control it <a class="header-anchor" href="#control-it" aria-label="Permalink to &quot;Control it&quot;">​</a></h2><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // off entirely</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;formatter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // or per-server: tune, disable, or extend</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;formatter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;prettier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;disabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;rustfmt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rustfmt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--edition&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2021&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.rs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;environment&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;RUSTFMT_CONFIG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/repo/rustfmt.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Custom entries must declare <code>extensions</code> (that&#39;s how a file routes to a command); the command receives the file path and rewrites it in place. <code>disabled: true</code> silences one built-in without turning off the rest — that&#39;s the knob when prettier and biome are both installed and you have <em>opinions</em>.</p><h2 id="failure-behavior" tabindex="-1">Failure behavior <a class="header-anchor" href="#failure-behavior" aria-label="Permalink to &quot;Failure behavior&quot;">​</a></h2><p>A formatter that errors is reported in the tool result — you see <em>why</em> the shape is unchanged instead of wondering — and it never blocks the edit itself from having happened. LSP diagnostics ride along with edit/write output separately; formatter + diagnostics together mean the agent usually self-corrects style <em>and</em> type errors before you review.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Debugging what would run: <code>/status</code> shows the loaded formatter inventory; set <code>&quot;formatter&quot;: false</code> and flip it back on to isolate a fight between the agent and your config.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./lsp.html">LSP</a> — Diagnostics, not cosmetics — the other half of self-correction. <ul><li><a href="./../reference/tools.html">Tools reference</a> — What edit/write do and return.</li><li><a href="./../reference/config.html">Config reference</a> — The <code>formatter</code> key.</li></ul></li></ul>`,13)])])}const u=e(n,[["render",r]]);export{k as __pageData,u as default};
